window.CARDS=window.CARDS||{};CARDS["people-miyake-akito"]=[{"i":"sc-miyake-akito-y1v5-p39-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke miyake-akito","q":"miyake akito ch 3  3  grip strength and the tug of war order miyake is named in the four way tug of war order that hirata sets by grip strength  takes the third tug of war slot behind sudou and ayanokoji   sudou kun  ayanokouji kun  miyake kun  and me","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v5-p39-1\"><h3><span class=\"ttl\">Ch.3 §3: Grip strength and the tug-of-war order<\/span><span class=\"meta\">Y1V5 · p.39–53<\/span><\/h3><p class=\"setup\">Miyake is named in the four-way tug-of-war order that Hirata sets by grip strength.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Takes the third tug-of-war slot behind Sudou and Ayanokōji: “Sudou-kun, Ayanokouji-kun, Miyake-kun, and me.”<span class=\"pg\">p.51<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v5-p123-1\">→ After: Ch.6 §6: left-side horse<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v5-p123-1","v":"y1v5","y":1,"o":6,"k":"","w":"hirata-yousuke sudou-ken miyake-akito","q":"miyake akito ch 6  6  left side horse miyake takes the left of ayanokoji s unit in the boys  cavalry   sudou centre  ayanokoji right  miyake left  hirata jockey  supports the jockey from the side  with ayanokoji has maybe half sudou s power against ryuuen s wall  rides in the class s strongest unit  cannot match sudou s crashes but holds the formation  yamada s power is called equal to sudou s while miyake and ayanokoji together are only about half of sudou each","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v5-p123-1\"><h3><span class=\"ttl\">Ch.6 §6: left-side horse<\/span><span class=\"meta\">Y1V5 · p.123–127<\/span><\/h3><p class=\"setup\">Miyake takes the left of Ayanokōji’s unit in the boys’ cavalry — Sudou centre, Ayanokōji right, Miyake left, Hirata jockey.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Supports the jockey from the side; with Ayanokōji has maybe half Sudou’s power against Ryuuen’s wall.<span class=\"pg\">p.123–127<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Rides in the class’s strongest unit; cannot match Sudou’s crashes but holds the formation.<span class=\"pg\">p.123–127<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Yamada’s power is called equal to Sudou’s while Miyake and Ayanokōji together are only about half of Sudou each.<span class=\"pg\">p.127<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v5-p39-1\">← Before: Ch.3 §3: Grip strength and the tug-of-war order<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v5-p182-1\">→ After: Ch.9 §9: ankle withdrawal<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v5-p182-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ayanokouji-kiyotaka miyake-akito","q":"miyake akito ch 9  9  ankle withdrawal miyake asks out of the 1200 metre relay after twisting his ankle in the 200 metre dash before lunch   sorry  but would you please let me withdraw  too   to tell you the truth  i twisted my ankle before lunch during the 200 meter dash  i thought it would feel better after i rested  but it still hurts   you will  ayanokouji  miyake asked   wait  though  are you that fast  questions ayanokouji s speed when he volunteers as replacement","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v5-p182-1\"><h3><span class=\"ttl\">Ch.9 §9: ankle withdrawal<\/span><span class=\"meta\">Y1V5 · p.182–184<\/span><\/h3><p class=\"setup\">Miyake asks out of the 1200-metre relay after twisting his ankle in the 200-metre dash before lunch.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Sorry, but…would you please let me withdraw, too?”<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\">“To tell you the truth, I twisted my ankle before lunch during the 200-meter dash. I thought it would feel better after I rested, but it still hurts.”<span class=\"pg\">p.182<\/span><\/li><li class=\"q spoken\">“You will, Ayanokouji?” Miyake asked. “Wait, though. Are you that fast?”<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Questions Ayanokouji’s speed when he volunteers as replacement.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v5-p123-1\">← Before: Ch.6 §6: left-side horse<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v5-p183-1\">→ After: Ch.9: a passing mention<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v5-p183-1","v":"y1v5","y":1,"o":6,"k":"","w":"miyake-akito","q":"miyake akito ch 9  a passing mention named when hirata and ayanokouji account for the ankle that forced the relay substitution   yeah  miyake s injury was unexpected  ayanokouji replies  the plan from the start had assumed miyake","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v5-p183-1\"><h3><span class=\"ttl\">Ch.9: a passing mention<\/span><span class=\"meta\">Y1V5 · p.183<\/span><\/h3><p class=\"setup\">Named when Hirata and Ayanokouji account for the ankle that forced the relay substitution.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Yeah. Miyake’s injury was unexpected,” Ayanokouji replies; the plan from the start had assumed Miyake.<span class=\"pg\">p.183<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v5-p182-1\">← Before: Ch.9 §9: ankle withdrawal<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v6-p85-1","v":"y1v6","y":1,"o":7,"k":"spoken","w":"hirata-yousuke hasebe-haruka kushida-kikyou yukimura-teruhiko ayanokouji-kiyotaka ishizaki-daichi miyake-akito","q":"miyake akito ch 5  5 2 5 5  the pair that thinks alike approaches horikita with hasebe  midterms show near identical averages and near identical wrong answers   well  yes  we re partners  but we re equally good and bad at all the same subjects  we re a little nervous about how we ll perform in the final  so we wanted to ask for your advice  hands hirata both short quiz and midterm sheets  apologises for the cruise ship and sports festival   i m sorry to bother you  hirata  really   i m always causing trouble for you  between the cruise ship and the sports festival  partner across the short quiz split  79 vs 1  walks out of the first tutoring offer  then rejoins at pallet under yukimura  declines kushida s one on one offer   not comfortable with a girls only group   i ll pass  i don t really feel like i could study with a group of just girls  i ll try and do it on my own  yukimura s main tutee  explains hasebe s exit  takes club time off for the sessions   hasebe isn t like that   maybe she just went on ahead of us   a bunch of different reasons   don t sweat it  yukimura  hasebe s just like this   you should be a little more careful about what you say   but ayanokouji was awesome in the relay  recalls the track scout after ayanokoji s relay run   did you do track and field back in junior high  ayanokouji  after seeing you run  a talent scout from the track and field club came looking for you   i wouldn t do it if it wasn t fun  by the way  you don t shoot the bow  just arrows   i took time off   when something takes priority  i focus on it  besides  my club s pretty lenient  library origin of their friendship  both independent and awkward in the group   well  hasebe came and talked to me when i was studying in the library one day   i feel the same  in a way   even in this group  i feel awkward and distant  present at pallet when class c s cake order roars at the cashier  no interest in the scene  same three correct and six wrong as hasebe on yukimura s drill   do you think this is going to be easy   yeah  you re right  i m sure class c will try to trip us up   no  i wouldn t even be able to think of a question   that s certainly a good idea  surprised she is not backing out this time   i thought you were going to back out  hasebe  this is unusual  you don t normally want to get involved in anything","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v6-p85-1\"><h3><span class=\"ttl\">Ch.5 §5.2–5.5: the pair that thinks alike<\/span><span class=\"meta\">Y1V6 · p.85–103<\/span><\/h3><p class=\"setup\">Approaches Horikita with Hasebe; midterms show near-identical averages and near-identical wrong answers.<\/p><p class=\"with\">with <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Well, yes. We’re partners, but we’re equally good and bad at all the same subjects. We’re a little nervous about how we’ll perform in the final, so we wanted to ask for your advice.”<span class=\"pg\">p.85<\/span><\/li><li class=\"q spoken\">“I’m sorry to bother you, Hirata, really.”<span class=\"pg\">p.85<\/span><\/li><li class=\"q spoken\">“I’m always causing trouble for you, between the cruise ship and the sports festival.”<span class=\"pg\">p.85<\/span><\/li><\/ul><details class=\"more\"><summary>28 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hands Hirata both short-quiz and midterm sheets; apologises for the cruise ship and sports festival.<span class=\"pg\">p.85<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Partner across the short-quiz split (79 vs 1); walks out of the first tutoring offer, then rejoins at Pallet under Yukimura.<span class=\"pg\">p.85–103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Declines Kushida’s one-on-one offer — not comfortable with a girls-only group.<span class=\"pg\">p.86<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll pass. I don’t really feel like I could study with a group of just girls. I’ll try and do it on my own,”<span class=\"pg\">p.87<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Yukimura’s main tutee; explains Hasebe’s exit; takes club time off for the sessions.<span class=\"pg\">p.89–103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hasebe isn’t like that,”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe she just went on ahead of us?”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A bunch of different reasons.”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t sweat it, Yukimura. Hasebe’s just like this,”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You should be a little more careful about what you say,”<span class=\"pg\">p.89<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But Ayanokouji was awesome in the relay.”<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Recalls the track scout after Ayanokōji’s relay run.<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Did you do track and field back in junior high, Ayanokouji? After seeing you run, a talent scout from the track and field club came looking for you,”<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wouldn’t do it if it wasn’t fun. By the way, you don’t shoot the bow, just arrows,”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I took time off.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When something takes priority, I focus on it. Besides, my club’s pretty lenient.”<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Library origin of their friendship; both independent and awkward in the group.<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, Hasebe came and talked to me when I was studying in the library one day,”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I feel the same, in a way.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Even in this group, I feel awkward and distant.”<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Present at Pallet when Class C’s cake order roars at the cashier; no interest in the scene.<span class=\"pg\">p.94–95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Same three correct and six wrong as Hasebe on Yukimura’s drill.<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you think this is going to be easy?”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yeah, you’re right. I’m sure Class C will try to trip us up.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. I wouldn’t even be able to think of a question.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s certainly a good idea,”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Surprised she is not backing out this time.<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I thought you were going to back out, Hasebe. This is unusual. You don’t normally want to get involved in anything.”<span class=\"pg\">p.102<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p132-1\">→ After: Ch.6 §6.0: the archery boy who stands up to Ryuuen<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v6-p132-1","v":"y1v6","y":1,"o":7,"k":"action spoken","w":"ishizaki-daichi ryuuen-kakeru yoshimoto-kosetsu hasebe-haruka miyake-akito","q":"miyake akito ch 6  6 0  the archery boy who stands up to ryuuen fifth session  archery club already tense enough  so he prefers the cafe to a stuffy room   yeah  archery club is already quiet and tense enough   it s just  there are clearly way more questions here than last time  and they look harder   come on  hasebe   i finally got a break from club stuff  but i don t want to spend all my free time studying  can i head back after i finish   i want to be in the club  i just also want free time   yoshimoto kousetsu  yeah  he s in the archery club   nope  but  come to think of it  he s been in a real hurry to leave as soon as club ends lately  that must be why   you re having even more sugar  your coffee s so ridiculously sweet  i m shocked you can drink it  when ryuuen s group stomps hasebe s cup  miyake stands and tells ryuuen to knock it off   hey  ryuuen  knock it off   i wasn t talking to you  lackeys should mind their own business  ishizaki   what the hell do you want  ryuuen   we re busy  if you ve got something to say  say it  shakes off ishizaki s collar grab and holds ryuuen s gaze in a monitored cafe   the calmest class d answer to class c pressure in the volume so far  collar grab and dismissal  lackeys should mind their own business  direct challenge in the cafe  ryuuen later targets the study group s  gift  instead of him  archery clubmate  confirms the second year girlfriend story  study partner  nicknames and coffee mockery","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v6-p132-1\"><h3><span class=\"ttl\">Ch.6 §6.0: the archery boy who stands up to Ryuuen<\/span><span class=\"meta\">Y1V6 · p.132–137<\/span><\/h3><p class=\"setup\">Fifth session; archery club already tense enough, so he prefers the café to a stuffy room.<\/p><p class=\"with\">with <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"index.html#yoshimoto-kosetsu\">Yoshimoto Kosetsu<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Yeah. Archery club is already quiet and tense enough,”<span class=\"pg\">p.132<\/span><\/li><li class=\"q spoken\">“It’s just… There are clearly way more questions here than last time, and they look harder.”<span class=\"pg\">p.133<\/span><\/li><li class=\"q spoken\">“Come on, Hasebe.”<span class=\"pg\">p.133<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I finally got a break from club stuff, but I don’t want to spend all my free time studying. Can I head back after I finish?”<span class=\"pg\">p.133<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I want to be in the club. I just also want free time,”<span class=\"pg\">p.134<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yoshimoto Kousetsu? Yeah, he’s in the archery club.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Nope. But, come to think of it, he’s been in a real hurry to leave as soon as club ends lately. That must be why.”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re having even more sugar? Your coffee’s so ridiculously sweet, I’m shocked you can drink it,”<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> When Ryuuen’s group stomps Hasebe’s cup, Miyake stands and tells Ryuuen to knock it off.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, Ryuuen. Knock it off.”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I wasn’t talking to you. Lackeys should mind their own business, Ishizaki,”<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What the hell do you want, Ryuuen?”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’re busy. If you’ve got something to say, say it.”<span class=\"pg\">p.137<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Shakes off Ishizaki’s collar grab and holds Ryuuen’s gaze in a monitored café — the calmest Class D answer to Class C pressure in the volume so far.<span class=\"pg\">p.136–137<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Collar grab and dismissal: lackeys should mind their own business.<span class=\"pg\">p.136<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Direct challenge in the café; Ryuuen later targets the study group’s “gift” instead of him.<span class=\"pg\">p.136–137<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yoshimoto Kosetsu<\/b> Archery clubmate; confirms the second-year girlfriend story.<span class=\"pg\">p.135<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Study partner; nicknames and coffee mockery.<span class=\"pg\">p.132–135<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p85-1\">← Before: Ch.5 §5.2–5.5: the pair that thinks alike<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p138-1\">→ After: Ch.6: passing mentions<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v6-p138-1","v":"y1v6","y":1,"o":7,"k":"spoken","w":"hasebe-haruka miyake-akito","q":"miyake akito ch 6  passing mentions group chat replies after hasebe s ice cream post  yukimura covers for ayanokoji s trouble  miyake at the table  named across cafe and group forming margins where he is not the section s focus  ryuuen s exit leaves the cafe lively around miyake s table  names shiina hiyori from class c when she orders  spy talk  ayanokouji san spends a lot of time with horikita san  complains class c wasted study time  hasebe counters they still worked  suggests kushida would be good for tutoring because she gets along with everyone   well  you and ayanon are like me and miyacchi  we re all loners  right  nickname debate  yukimura refuses miyacchi  group chat replies after hasebe s ice cream post  sakura thanks miyake kun and yukimura kun in the invitation round  horikita asks whether hasebe and miyake kun s issues are resolved","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v6-p138-1\"><h3><span class=\"ttl\">Ch.6: passing mentions<\/span><span class=\"meta\">Y1V6 · p.138, 140–141, 143–146, 149–151, 153, 164<\/span><\/h3><p class=\"setup\">Named across café and group-forming margins where he is not the section’s focus.<\/p><p class=\"with\">with <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hasebe Haruka<\/b> “Well, you and Ayanon are like me and Miyacchi. We’re all loners, right?”<span class=\"pg\">p.149<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Group-chat replies after Hasebe’s ice-cream post.<span class=\"pg\">p.144<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Yukimura covers for Ayanokōji’s trouble; Miyake at the table.<span class=\"pg\">p.145<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ryuuen’s exit leaves the café lively around Miyake’s table.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Names Shiina Hiyori from Class C when she orders.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Spy talk: Ayanokouji-san spends a lot of time with Horikita-san.<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Complains Class C wasted study time; Hasebe counters they still worked.<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Suggests Kushida would be good for tutoring because she gets along with everyone.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Nickname debate: Yukimura refuses Miyacchi.<span class=\"pg\">p.150<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Group-chat replies after Hasebe’s ice-cream post.<span class=\"pg\">p.151<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Sakura thanks Miyake-kun and Yukimura-kun in the invitation round.<span class=\"pg\">p.153<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Horikita asks whether Hasebe and Miyake-kun’s issues are resolved.<span class=\"pg\">p.164<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p132-1\">← Before: Ch.6 §6.0: the archery boy who stands up to Ryuuen<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p156-1\">→ After: Ch.6 §6.4: late but in<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v6-p156-1","v":"y1v6","y":1,"o":7,"k":"spoken","w":"hasebe-haruka yukimura-teruhiko miyake-akito","q":"miyake akito ch 6  6 4  late but in answers the group chat movie plan after the others have already committed   sounds good to me   can you reserve our tickets  her condition for yukimura s yes  attendance gate for keisei","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v6-p156-1\"><h3><span class=\"ttl\">Ch.6 §6.4: late but in<\/span><span class=\"meta\">Y1V6 · p.156<\/span><\/h3><p class=\"setup\">Answers the group-chat movie plan after the others have already committed.<\/p><p class=\"with\">with <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Sounds good to me.”<span class=\"pg\">p.156<\/span><\/li><li class=\"q spoken\">“Can you reserve our tickets?”<span class=\"pg\">p.156<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Her condition for Yukimura’s yes.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Attendance gate for Keisei.<span class=\"pg\">p.156<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p138-1\">← Before: Ch.6: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p185-1\">→ After: Ch.7: named as a hardest-hit average<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v6-p185-1","v":"y1v6","y":1,"o":7,"k":"","w":"hasebe-haruka miyake-akito","q":"miyake akito ch 7  named as a hardest hit average named with haruka as the average students the difficult humanities will hit hardest  named only in ayanokoji s difficulty analysis  they must ace the humanities  the first subject lineup is cruel for students like them  paired with her as the average case hardest hit","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v6-p185-1\"><h3><span class=\"ttl\">Ch.7: named as a hardest-hit average<\/span><span class=\"meta\">Y1V6 · p.185, 193<\/span><\/h3><p class=\"setup\">Named with Haruka as the average students the difficult humanities will hit hardest.<\/p><p class=\"with\">with <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Named only in Ayanokōji’s difficulty analysis: they must ace the humanities; the first subject lineup is cruel for students like them.<span class=\"pg\">p.185, 193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Paired with her as the average-case hardest hit.<span class=\"pg\">p.185, 193<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v6-p156-1\">← Before: Ch.6 §6.4: late but in<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v7-p14-1","v":"y1v7","y":1,"o":8,"k":"spoken","w":"komiya-kyogo ishizaki-daichi ryuuen-kakeru hasebe-haruka yukimura-teruhiko karuizawa-kei miyake-akito","q":"miyake akito ch 2  akito  club  and the tail report arrives late from archery club to the keyaki mall table  reports komiya and ishizaki s glare session   so  only one class can be a in the end  huh   like normal  not really great  not really bad  you don t have to pretend to be interested   back in junior high  an upperclassman i was friends with belonged to the archery club  so  i thought i d give it a shot  that s all there was to it  no particularly deep reason   sorry to change the topic  but i was wondering about something   well  they sent different people this time around  komiya and ishizaki showed up today at archery club  they said they came to observe  which the upperclassmen readily accepted  but they just glared at me the entire time   i suppose i understand his desperation   we had all that trouble with rations and sanitation  someone burned our manual  and someone s underwear even got stolen  class d was in complete shambles  we didn t have the time or energy to conduct reconnaissance on other classes   sadly  archery is my only love  named as the class c henchman watching the mall group  with komiya at archery club  glaring through practice  most bothered by ryuuen s surveillance  pleased at the thought of ryuuen s pride taking a hit  texted by her  teased about archery and girlfriends  hands ayanokoji the too sweet mango juice  leaves academics to him on the class a climb  names her with hirata as class d s only couple  club bound so he misses the early mall hours  reads ryuuen s pressure accurately  embarrassed about both archery and dating  loyal enough to report the tail without proof  fifth group member  absent until p 15 because of club  blank scan  footer only","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v7-p14-1\"><h3><span class=\"ttl\">Ch.2: Akito, club, and the tail report<\/span><span class=\"meta\">Y1V7 · p.14–28<\/span><\/h3><p class=\"setup\">Arrives late from archery club to the Keyaki Mall table; reports Komiya and Ishizaki’s glare session.<\/p><p class=\"with\">with <a href=\"komiya-kyogo.html\">Komiya Kyogo<\/a> · <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“So, only one class can be A in the end, huh?”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\">“Like normal. Not really great, not really bad. You don’t have to pretend to be interested,”<span class=\"pg\">p.15<\/span><\/li><li class=\"q spoken\">“Back in junior high, an upperclassman I was friends with belonged to the archery club. So, I thought I’d give it a shot. That’s all there was to it. No particularly deep reason,”<span class=\"pg\">p.16<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Sorry to change the topic, but I was wondering about something,”<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, they sent different people this time around. Komiya and Ishizaki showed up today at archery club. They said they came to observe, which the upperclassmen readily accepted. But they just glared at me the entire time,”<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I suppose I understand his desperation,”<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We had all that trouble with rations and sanitation, someone burned our manual, and someone’s underwear even got stolen. Class D was in complete shambles. We didn’t have the time or energy to conduct reconnaissance on other classes,”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sadly, archery is my only love,”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Komiya Kyogo<\/b> Named as the Class C henchman watching the mall group.<span class=\"pg\">p.17–18<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> With Komiya at archery club, glaring through practice.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Most bothered by Ryuuen’s surveillance; pleased at the thought of Ryuuen’s pride taking a hit.<span class=\"pg\">p.18, 20<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Texted by her; teased about archery and girlfriends; hands Ayanokōji the too-sweet mango juice.<span class=\"pg\">p.15–16, 26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Leaves academics to him on the Class A climb.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Names her with Hirata as Class D’s only couple.<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Club-bound so he misses the early mall hours; reads Ryuuen’s pressure accurately; embarrassed about both archery and dating; loyal enough to report the tail without proof.<span class=\"pg\">p.14–28<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Fifth group member, absent until p.15 because of club.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank scan (footer only).<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p33-1\">→ After: Ch.3: club-skip and the Komiya read<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v7-p33-1","v":"y1v7","y":1,"o":8,"k":"spoken","w":"komiya-kyogo ryuuen-kakeru ayanokouji-kiyotaka kouenji-rokusuke hasebe-haruka yukimura-teruhiko miyake-akito","q":"miyake akito ch 3  club skip and the komiya read skips archery to meet the group  first to clock komiya s return to keyaki mall   i m skipping today   looks like those class c dudes showed up at archery again  it doesn t seem like they threw punches or got into any fights  though   i told the seniors i felt distracted  so i was going to take today off  the club s pretty lenient   there s nothing the teacher can really do  if class c trespassed in our private places  that d be one thing  but they re free to observe the archery club   so  you ve been marked too  ayanokouji  does that ryuuen dude hate the thought of losing to class d that much   are you all right  keisei   i usually finish up with club stuff and meet you guys kind of late  right   there re usually an awful lot of class c students around  considering the time  when i met up with you guys the other day at keyaki mall  komiya was there  he s here today  too   don t  we don t know what they re after  it s better not to react   we don t know whether or not that person exists   ryuuen spews lies as easily as breathing   that s assuming that there s any rhyme or reason to ryuuen s thinking   absolutely not   he s nuts   what a drag  hey  if they give you trouble  feel free to talk to us about it  the tail he names twice   yesterday and today at the mall  reads the surveillance as ryuuen s hate of losing to class d  marks him too  offers a shoulder  joins the mastermind vote against kouenji   he s nuts    island retirement kills the candidate  club skip partner  stops her from staring at komiya  defends against the mastermind theory with him  blunt about club policy  sharpest observer in the group  keeps the table from reacting to the tail","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v7-p33-1\"><h3><span class=\"ttl\">Ch.3: club-skip and the Komiya read<\/span><span class=\"meta\">Y1V7 · p.33, 36, 47–53<\/span><\/h3><p class=\"setup\">Skips archery to meet the group; first to clock Komiya’s return to Keyaki Mall.<\/p><p class=\"with\">with <a href=\"komiya-kyogo.html\">Komiya Kyogo<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I’m skipping today.”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\">“Looks like those Class C dudes showed up at archery again. It doesn’t seem like they threw punches or got into any fights, though.”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\">“I told the seniors I felt distracted, so I was going to take today off. The club’s pretty lenient,”<span class=\"pg\">p.48<\/span><\/li><\/ul><details class=\"more\"><summary>19 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “There’s nothing the teacher can really do. If Class C trespassed in our private places, that’d be one thing, but they’re free to observe the archery club,”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, you’ve been marked too, Ayanokouji. Does that Ryuuen dude hate the thought of losing to Class D that much?”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Are you all right, Keisei?”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I usually finish up with club stuff and meet you guys kind of late, right?”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’re usually an awful lot of Class C students around, considering the time. When I met up with you guys the other day at Keyaki Mall, Komiya was there. He’s here today, too,”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t. We don’t know what they’re after. It’s better not to react,”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We don’t know whether or not that person exists,”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ryuuen spews lies as easily as breathing.”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s assuming that there’s any rhyme or reason to Ryuuen’s thinking,”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Absolutely not,”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “He’s nuts.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What a drag. Hey, if they give you trouble, feel free to talk to us about it,”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Komiya Kyogo<\/b> The tail he names twice — yesterday and today at the mall.<span class=\"pg\">p.50–51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Reads the surveillance as Ryuuen’s hate of losing to Class D.<span class=\"pg\">p.49, 51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Marks him too; offers a shoulder; joins the mastermind vote against Kouenji.<span class=\"pg\">p.49–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> “He’s nuts.” — island retirement kills the candidate.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Club-skip partner; stops her from staring at Komiya.<span class=\"pg\">p.47–50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Defends against the mastermind theory with him.<span class=\"pg\">p.50–52<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Blunt about club policy; sharpest observer in the group; keeps the table from reacting to the tail.<span class=\"pg\">p.33, 47–53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p14-1\">← Before: Ch.2: Akito, club, and the tail report<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p36-1\">→ After: Ch.3: the study-group line<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v7-p36-1","v":"y1v7","y":1,"o":8,"k":"","w":"miyake-akito","q":"miyake akito ch 3  the study group line passing mention  horikita notes a study group formed specifically to help hasebe san and miyake","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v7-p36-1\"><h3><span class=\"ttl\">Ch.3: the study-group line<\/span><span class=\"meta\">Y1V7 · p.36<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: Horikita notes a study group formed specifically to help Hasebe-san and Miyake.<span class=\"pg\">p.36<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p33-1\">← Before: Ch.3: club-skip and the Komiya read<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p90-1\">→ After: Ch.3: club check, cold preference, Ichinose counter<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v7-p90-1","v":"y1v7","y":1,"o":8,"k":"spoken","w":"hasebe-haruka sakura-airi yukimura-teruhiko ichinose-honami miyake-akito","q":"miyake akito ch 3  club check  cold preference  ichinose counter sunday starts with his club  ends the day as the only group member who likes the cold and the one who walks back the rotten ichinose hope   hey  i saved you from the last one  it was seriously spicy  said akito  he d ended that particular hot streak   i don t handle it well  either   well  a little chilliness is good for me  it means i don t sweat during club  which makes practicing easy  said akito  making him the only member of the group to prefer the cold   you have a point  she s so flawless it s almost creepy  saying you hope she s rotten inside is going a bit too far  though  said akito  spicy rescue  counters her ichinose take  karaoke and walk partner  the takoyaki streak he helps end  named in the perfection debate without meeting her  practical about cold and club  the group s brake on vicious gossip","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v7-p90-1\"><h3><span class=\"ttl\">Ch.3: club check, cold preference, Ichinose counter<\/span><span class=\"meta\">Y1V7 · p.90–95<\/span><\/h3><p class=\"setup\">Sunday starts with his club; ends the day as the only group member who likes the cold and the one who walks back the rotten-Ichinose hope.<\/p><p class=\"with\">with <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"sakura-airi.html\">Sakura Airi<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hey, I saved you from the last one. It was seriously spicy,” said Akito. He’d ended that particular hot streak.<span class=\"pg\">p.91<\/span><\/li><li class=\"q spoken\">“I don’t handle it well, either.”<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\">“Well, a little chilliness is good for me. It means I don’t sweat during club, which makes practicing easy,” said Akito, making him the only member of the group to prefer the cold.<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “You have a point. She’s so flawless it’s almost creepy. Saying you hope she’s rotten inside is going a bit too far, though,” said Akito.<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Spicy rescue; counters her Ichinose take.<span class=\"pg\">p.91, 94–95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Karaoke and walk partner.<span class=\"pg\">p.91, 94–95<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> The takoyaki streak he helps end.<span class=\"pg\">p.90–91<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Named in the perfection debate without meeting her.<span class=\"pg\">p.95<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Practical about cold and club; the group’s brake on vicious gossip.<span class=\"pg\">p.90–95<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p36-1\">← Before: Ch.3: the study-group line<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p100-1\">→ After: Ch.4: named in the smoke-out<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v7-p100-1","v":"y1v7","y":1,"o":8,"k":"spoken","w":"ayanokouji-kiyotaka ryuuen-kakeru yukimura-teruhiko miyake-akito","q":"miyake akito ch 4  named in the smoke out asks whether the group should follow  trails the path  named acceptable by ryuuen s bait   should we go check it out  kiyotaka  asked akito   they may have something planned   it s like he thinks he s a king  bossing his classmates around just by moving his chin  he spat  asks him first  trails with yukimura  named in the acceptable trio  answered with the born this way line  the pair ayanokoji asks to wait with him  first to propose action  blunt on ryuuen s chin king posture","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v7-p100-1\"><h3><span class=\"ttl\">Ch.4: named in the smoke-out<\/span><span class=\"meta\">Y1V7 · p.100–107<\/span><\/h3><p class=\"setup\">Asks whether the group should follow; trails the path; named acceptable by Ryuuen’s bait.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Should we go check it out, Kiyotaka?” asked Akito.<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">“They may have something planned.”<span class=\"pg\">p.100<\/span><\/li><li class=\"q spoken\">“It’s like he thinks he’s a king. Bossing his classmates around just by moving his chin,” he spat.<span class=\"pg\">p.107<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks him first; trails with Yukimura.<span class=\"pg\">p.100–101<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Named in the acceptable trio; answered with the born-this-way line.<span class=\"pg\">p.106–107<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> The pair Ayanokōji asks to wait with him.<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> First to propose action; blunt on Ryuuen’s chin-king posture.<span class=\"pg\">p.100–107<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p90-1\">← Before: Ch.3: club check, cold preference, Ichinose counter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p120-1\">→ After: Ch.5 §5.1: on the tail list<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v7-p120-1","v":"y1v7","y":1,"o":8,"k":"","w":"ryuuen-kakeru miyake-akito","q":"miyake akito ch 5  5 1  on the tail list named among the delinquents class c is tailing after the paper shuffle  grouped with sudou as a weakling excluded suspect class  hirata is the conservative contrast  ishizaki and the other guys were ordered to keep an eye on miyake and a few more people  ibuki and the rest are not told the real reason  one of the class d students his surveillance net watches","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v7-p120-1\"><h3><span class=\"ttl\">Ch.5 §5.1: on the tail list<\/span><span class=\"meta\">Y1V7 · p.120, 123<\/span><\/h3><p class=\"setup\">Named among the delinquents Class C is tailing after the Paper Shuffle.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Grouped with Sudou as a weakling-excluded suspect class; Hirata is the conservative contrast.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Ishizaki and the other guys were ordered to keep an eye on Miyake and a few more people; Ibuki and the rest are not told the real reason.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> One of the Class D students his surveillance net watches.<span class=\"pg\">p.120–123<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p100-1\">← Before: Ch.4: named in the smoke-out<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p154-1\">→ After: Ch.6: Akito’s tail report and his mother<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v7-p154-1","v":"y1v7","y":1,"o":8,"k":"spoken","w":"ayanokouji-kiyotaka ryuuen-kakeru hasebe-haruka miyake-akito","q":"miyake akito ch 6  akito s tail report and his mother walks silently with the group  then reports no one is tailing them   no sign of anyone tailing us  mumbles it  sounding relieved  ryuuen s plan to settle things today made tailing unnecessary   my mom s a worrywart  she s probably really anxious   that might worry her even more  guess i should study a little harder   but it s only two  checks the time on his phone when ayanokoji suddenly turns back  stern and watchful on the walk  tender about family contact rules under the school s three year silence  group member who notices the all nighter excuse  the class c threat whose tailing has just stopped  fellow group walker","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v7-p154-1\"><h3><span class=\"ttl\">Ch.6: Akito’s tail report and his mother<\/span><span class=\"meta\">Y1V7 · p.154–156<\/span><\/h3><p class=\"setup\">Walks silently with the group, then reports no one is tailing them.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“No sign of anyone tailing us,”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\">“My mom’s a worrywart. She’s probably really anxious,”<span class=\"pg\">p.155<\/span><\/li><li class=\"q spoken\">“That…might worry her even more. Guess I should study a little harder,”<span class=\"pg\">p.155<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Mumbles it, sounding relieved; Ryuuen’s plan to settle things today made tailing unnecessary.<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it’s only two,”<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Checks the time on his phone when Ayanokōji suddenly turns back.<span class=\"pg\">p.156<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Stern and watchful on the walk; tender about family contact rules under the school’s three-year silence.<span class=\"pg\">p.154–156<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Group member who notices the all-nighter excuse.<span class=\"pg\">p.154–156<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> The Class C threat whose tailing has just stopped.<span class=\"pg\">p.155<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Fellow group walker.<span class=\"pg\">p.154–156<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v7-p120-1\">← Before: Ch.5 §5.1: on the tail list<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v8-p11-1","v":"y1v8","y":1,"o":10,"k":"","w":"ayanokouji-kiyotaka miyake-akito","q":"miyake akito ch 2  named in the ayanokoji group chat not on the bus dialogue line  named in the group chat ayanokoji opens after texting horikita and kei  passing mention   keisei  akito  and even airi and haruka all happily discussed the exam  in the ayanokoji group thread  listed among the friends ayanokoji hopes will not be expelled  though they are not his top priority protectees","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v8-p11-1\"><h3><span class=\"ttl\">Ch.2: named in the Ayanokōji Group chat<\/span><span class=\"meta\">Y1V8 · p.11–43<\/span><\/h3><p class=\"setup\">Not on the bus dialogue line; named in the group chat Ayanokōji opens after texting Horikita and Kei.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “Keisei, Akito, and even Airi and Haruka all happily discussed the exam” in the Ayanokōji Group thread.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Listed among the friends Ayanokōji hopes will not be expelled, though they are not his top-priority protectees.<span class=\"pg\">p.30, 32<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p44-1\">→ After: Ch.2: the Ryuuen seat for the lion’s share<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v8-p44-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ryuuen-kakeru nagumo-miyabi miyake-akito","q":"miyake akito ch 2  the ryuuen seat for the lion s share with yukimura at the gym edge  he proposes buying the unwanted ryuuen seat   i m thinking of sticking with keisei  i mean  using my head really isn t my strong suit   allow me to suggest something   in return  i want the lion s share of the reward for first place  offers to act as representative for whoever takes ryuuen  demanding the first place lion s share   ayanokoji suspects the real motive is getting someone to take ryuuen in  the only willing buyer of the poisoned seat when no one else will touch him  answers ayanokoji s mutter on why groups avoid nagumo   the rest of that second year group is  kind of iffy  reads kaneda s goda pick as reliable allies  not a snub of nagumo s person","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v8-p44-1\"><h3><span class=\"ttl\">Ch.2: the Ryuuen seat for the lion’s share<\/span><span class=\"meta\">Y1V8 · p.44–56<\/span><\/h3><p class=\"setup\">With Yukimura at the gym edge, he proposes buying the unwanted Ryuuen seat.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I’m thinking of sticking with Keisei. I mean, using my head really isn’t my strong suit.”<span class=\"pg\">p.44<\/span><\/li><li class=\"q spoken\">“ALLOW ME to suggest something.”<span class=\"pg\">p.50<\/span><\/li><li class=\"q spoken\">“In return, I want the lion’s share of the reward for first place.”<span class=\"pg\">p.50<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Goal<\/span> Offers to act as representative for whoever takes Ryuuen, demanding the first-place lion’s share — Ayanokōji suspects the real motive is getting someone to take Ryuuen in.<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> The only willing buyer of the poisoned seat when no one else will touch him.<span class=\"pg\">p.50–51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Answers Ayanokōji’s mutter on why groups avoid Nagumo — the rest of that second-year group is “kind of iffy.”<span class=\"pg\">p.56<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Reads Kaneda’s Gōda pick as reliable allies, not a snub of Nagumo’s person.<span class=\"pg\">p.56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p11-1\">← Before: Ch.2: named in the Ayanokōji Group chat<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p128-1\">→ After: Ch.4: named as the inside man in Ryuuen’s group<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v8-p128-1","v":"y1v8","y":1,"o":10,"k":"","w":"ryuuen-kakeru kanzaki-ryuuji miyake-akito","q":"miyake akito ch 4  named as the inside man in ryuuen s group not on the page  named when kanzaki reports three days without ryuuen rumors  passing mention   it was three days since akito had entered ryuuen s group  we hardly ever spoke  three days inside with no scheming reports   the quiet is what kanzaki and ayanokoji mark as probably true  bathhouse proximity exists but they barely speak  kanzaki s no rumor line is the channel  no further presence in chapter 4 after half 1","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v8-p128-1\"><h3><span class=\"ttl\">Ch.4: named as the inside man in Ryuuen’s group<\/span><span class=\"meta\">Y1V8 · p.128<\/span><\/h3><p class=\"setup\">Not on the page; named when Kanzaki reports three days without Ryuuen rumors.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention: “It was three days since Akito had entered Ryuuen’s group… we hardly ever spoke.”<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Three days inside with no scheming reports — the quiet is what Kanzaki and Ayanokōji mark as probably true.<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Bathhouse proximity exists but they barely speak; Kanzaki’s no-rumor line is the channel.<span class=\"pg\">p.128<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No further presence in chapter 4 after half 1.<span class=\"pg\">p.147<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p44-1\">← Before: Ch.2: the Ryuuen seat for the lion’s share<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p165-1\">→ After: Ch.6 half 1: the Ryuuen groups report<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v8-p165-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ryuuen-kakeru hasebe-haruka sakura-airi ishizaki-daichi ayanokouji-kiyotaka miyake-akito","q":"miyake akito ch 6 half 1  the ryuuen groups report ayanokoji group dinner  pressed on his class d group under ryuuen   well  i guess  i m keeping my guard up  but it doesn t seem there s been any change  he s actually taking the classes seriously and participating   yeah  he s acting so normal  it s almost scary  if anything  he s handling himself way better than the awkward guys  it s just  well  i ve tried talking to him a few times  but he doesn t seem to want to hang out with anyone   maybe he kind of went crazy from the shock of losing a fight   i dunno  i think this is just the way he s always been   not much to say  personally  i m not close with anyone in it  but i m not fighting with anyone either  airi and i are in the same group  so i m good   if anything  i d say ishizaki s the real problem child  maybe he s gotten carried away since ryuuen kun was defeated  not so long ago  he was just a lackey   come on  it s all right  i mean  if you girls are doing okay  that puts us at ease  right  reports him taking classes seriously  closed to socializing    this is just the way he s always been  same group with airi  her ryuuen question opens the report  confirms they share a group  names him the real problem child post ryuuen defeat  miyacchi s table report  ends on the girls are fine reassurance   keeping my guard up    the careful witness in ryuuen s group","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v8-p165-1\"><h3><span class=\"ttl\">Ch.6 half 1: the Ryuuen groups report<\/span><span class=\"meta\">Y1V8 · p.165–167<\/span><\/h3><p class=\"setup\">Ayanokōji Group dinner; pressed on his Class D group under Ryuuen.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"sakura-airi.html\">Sakura Airi<\/a> · <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Well, I guess. I’m keeping my guard up, but it doesn’t seem there’s been any change. He’s actually taking the classes seriously and participating.”<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\">“Yeah. He’s acting so normal, it’s almost scary. If anything, he’s handling himself way better than the awkward guys. It’s just, well, I’ve tried talking to him a few times, but he doesn’t seem to want to hang out with anyone.”<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\">“Maybe he kind of went crazy from the shock of losing a fight?”<span class=\"pg\">p.165<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I dunno. I think this is just the way he’s always been.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not much to say, personally. I’m not close with anyone in it, but I’m not fighting with anyone either. Airi and I are in the same group, so I’m good.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If anything, I’d say Ishizaki’s the real problem child. Maybe he’s gotten carried away since Ryuuen-kun was defeated. Not so long ago, he was just a lackey.”<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Come on, it’s all right. I mean, if you girls are doing okay, that puts us at ease. Right?”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Reports him taking classes seriously, closed to socializing — “this is just the way he’s always been.”<span class=\"pg\">p.165–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Same-group with Airi; her Ryuuen question opens the report.<span class=\"pg\">p.165–166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakura Airi<\/b> Confirms they share a group.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Names him the real problem child post-Ryuuen defeat.<span class=\"pg\">p.166<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Miyacchi’s table report; ends on the girls-are-fine reassurance.<span class=\"pg\">p.165–167<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> “Keeping my guard up” — the careful witness in Ryuuen’s group.<span class=\"pg\">p.165<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p128-1\">← Before: Ch.4: named as the inside man in Ryuuen’s group<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p185-1\">→ After: Ch.6 closer<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v8-p185-1","v":"y1v8","y":1,"o":10,"k":"","w":"miyake-akito","q":"miyake akito ch 6 closer no presence in chapter 6 after half 1","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v8-p185-1\"><h3><span class=\"ttl\">Ch.6 closer<\/span><span class=\"meta\">Y1V8 · p.185<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Limit<\/span> No presence in chapter 6 after half 1.<span class=\"pg\">p.185<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v8-p165-1\">← Before: Ch.6 half 1: the Ryuuen groups report<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v9-p41-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"hasebe-haruka ryuuen-kakeru hashimoto-masayoshi kanzaki-ryuuji ayanokouji-kiyotaka miyake-akito","q":"miyake akito club call and gymnasium standoff phone call on speaker from club duty  later standing watch between hashimoto and kanzaki in the gym   no  looks like trouble s brewing   class a and class b are quarreling  worst case scenario  i have to be there to stop them if a fight breaks out  answers haruka s call  ends it after saying the trouble could reach their class next  narration  his willingness to deal with ryuuen in the training camp and the old  bad himself  story explain his confidence  stands between the two first years  hashimoto tries to drag him into the argument  he stays until sure they will not fistfight   you re quite persistent  miyake  i wasn t the one who instigated this in the first place  kanzaki was  kanzaki wanted no audience  miyake refuses to leave until the de escalation is clear  asks ayanokoji what the group should do  accepts the stay and watch advice   hey  what should we do  physical barrier between two confrontational classmates without taking a side   his standing role in the scene  club activity not named on these pages beyond  done with club activities    archery is implied by the search path  not stated as his club in the quoted lines","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v9-p41-1\"><h3><span class=\"ttl\">Club call and gymnasium standoff<\/span><span class=\"meta\">Y1V9 · p.41–46<\/span><\/h3><p class=\"setup\">Phone call on speaker from club duty; later standing watch between Hashimoto and Kanzaki in the gym.<\/p><p class=\"with\">with <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“No… Looks like trouble’s brewing.”<span class=\"pg\">p.41<\/span><\/li><li class=\"q spoken\">“Class A and Class B are quarreling. Worst case scenario, I have to be there to stop them if a fight breaks out.”<span class=\"pg\">p.41<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hashimoto Masayoshi<\/b> “You’re quite persistent, Miyake. I wasn’t the one who instigated this in the first place, Kanzaki was.”<span class=\"pg\">p.43<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Answers Haruka’s call; ends it after saying the trouble could reach their class next.<span class=\"pg\">p.41–42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Narration: his willingness to deal with Ryuuen in the training camp and the old “bad himself” story explain his confidence.<span class=\"pg\">p.42<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Stands between the two first-years; Hashimoto tries to drag him into the argument; he stays until sure they will not fistfight.<span class=\"pg\">p.43–46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Kanzaki wanted no audience; Miyake refuses to leave until the de-escalation is clear.<span class=\"pg\">p.43–46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Asks Ayanokōji what the group should do; accepts the stay-and-watch advice.<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, what should we do?”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Physical barrier between two confrontational classmates without taking a side — his standing role in the scene.<span class=\"pg\">p.43<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Club activity not named on these pages beyond “done with club activities?” — archery is implied by the search path, not stated as his club in the quoted lines.<span class=\"pg\">p.41<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v9-p51-1\">→ After: Delinquent history and Ryuuen’s neighbourhood<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v9-p51-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"ryuuen-kakeru hasebe-haruka hashimoto-masayoshi miyake-akito","q":"miyake akito delinquent history and ryuuen s neighbourhood after the gym  the group walks back  haruka needles miyake about his past   i don t really wanna talk about it  haruka  i don t want it to spread around   let me just say this  i wasn t some famous delinquent  honestly  someone else was the top delinquent at the school i went to  and he was much stronger than me   by the way  class d s ryuuen went to the middle school right next to mine  their middle schools were neighbours  school conflicts brought them into contact    that guy probably never took me very seriously  asks her to keep the talk inside the group  answers her  were you really strong  with the top delinquent demotion  origin of his ease with confrontation   grown up where  adults would live a disordered life  and kids were raised the same  present at the gym dispersal that prompts the walk and talk  asks that the conversation not spread outside the group  ayanokoji agrees it is somebody else s problem","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v9-p51-1\"><h3><span class=\"ttl\">Delinquent history and Ryuuen’s neighbourhood<\/span><span class=\"meta\">Y1V9 · p.51–52<\/span><\/h3><p class=\"setup\">After the gym, the group walks back; Haruka needles Miyake about his past.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I don’t really wanna talk about it, Haruka. I don’t want it to spread around.”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\">“Let me just say this, I wasn’t some famous delinquent. Honestly, someone else was the top delinquent at the school I went to, and he was much stronger than me.”<span class=\"pg\">p.52<\/span><\/li><li class=\"q spoken\">“By the way, Class D’s Ryuuen went to the middle school right next to mine.”<span class=\"pg\">p.52<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Their middle schools were neighbours; school conflicts brought them into contact — “that guy probably never took me very seriously.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Asks her to keep the talk inside the group; answers her “were you really strong?” with the top-delinquent demotion.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Origin of his ease with confrontation — grown up where “adults would live a disordered life” and kids were raised the same.<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Present at the gym dispersal that prompts the walk-and-talk.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Asks that the conversation not spread outside the group; Ayanokōji agrees it is somebody else’s problem.<span class=\"pg\">p.52<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v9-p41-1\">← Before: Club call and gymnasium standoff<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v9-p107-1\">→ After: Chocolate in the circle; the friend-group guess<\/button><\/div><\/article>"},{"i":"sc-miyake-akito-y1v9-p107-1","v":"y1v9","y":1,"o":11,"k":"","w":"hasebe-haruka hashimoto-masayoshi miyake-akito","q":"miyake akito chocolate in the circle  the friend group guess a class b girl offers akito a box of chocolates while the boys stew  hashimoto guesses ayanokoji may be with yukimura  miyake and that group   then dismisses it  named in the classroom scenes  no direct speech this chapter","h":"<article class=\"card\" id=\"sc-miyake-akito-y1v9-p107-1\"><h3><span class=\"ttl\">Chocolate in the circle; the friend-group guess<\/span><span class=\"meta\">Y1V9 · p.107, 122<\/span><\/h3><p class=\"with\">with <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> A Class B girl offers Akito a box of chocolates while the boys stew.<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Hashimoto guesses Ayanokōji may be with Yukimura, Miyake and that group — then dismisses it.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Named in the classroom scenes; no direct speech this chapter.<span class=\"pg\">p.107, 122<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-miyake-akito-y1v9-p51-1\">← Before: Delinquent history and Ryuuen’s neighbourhood<\/button><\/div><\/article>"}];
